+const TOOL: &str = "EM-0800-4FL";
+
+fn fig8_params() -> OpParams {
+    OpParams::Adaptive2D {
+        stepover: 3.0,
+        stock_to_leave: 0.0,
+        clearance_z: Height::fixed(27.0),
+        retract_z: None,
+        top_z: Height::fixed(20.0),
+        bottom_z: Height::fixed(15.0),
+        stepdown: 5.0,
+        feed: 2400.0,
+        plunge_feed: 500.0,
+        climb: true,
+        entry: Entry3D::Helix,
+        helix_radius: 1.0,
+        optimal_load: DEFAULT_OPTIMAL_LOAD,
+        method: AdaptiveMethod::Spiral,
